  ('home', 'hero', 'hero', 'Hero', 0, true, '{"tag":"New name, same\nengineering DNA","line1":"Y{O|wide}UR","words":[{"text":"DIGITAL 360"},{"text":"SOFTWARE"},{"text":"PRODUCT"},{"text":"ALL-IN-ONE"}],"line3":"AGEN{c}Y","badge":{"label":"LET''S\nBUILD","href":"/quote"}}'::jsonb),
