  ('home', 'about', 'about', 'About (word fill)', 10, true, '{"label":"ABOUT US","paragraph":"We''re thinkers, makers, and coders, coffee lovers (mostly all), bug hunters, curious by nature, pragmatic by choice. We explore, question, and ship until the answer fits. Every project is a journey, and we''re here for the ride.","link":{"label":"BUILD MORE WITH US","href":"/contact"},"photos":[]}'::jsonb),
  ('home', 'process', 'process', 'Process', 11, true, '{"label":"HOW WE WORK","title":"FROM IDEA\nTO LAUNCH","steps":[{"title":"Discovery","duration":"1–2 weeks","text":"We learn your business, users and goals, audit what exists and agree on scope, budget and success metrics."},{"title":"Design","duration":"1–2 weeks","text":"Wireframes, then high-fidelity screens and a clickable prototype. You approve every screen before we write code."},{"title":"Development","duration":"2–3 weeks","text":"Clean, tested code in short sprints with a live staging link, so you see progress every few days."},{"title":"Launch","duration":"1 week","text":"Performance, SEO and security checks, analytics, go-live and a handover session for your team."},{"title":"Support","duration":"Ongoing","text":"Monitoring, updates, backups and new features on a monthly plan, with a 24-hour response time."}]}'::jsonb),
