insert into public.services (published, cover_url, seo_title, seo_description, slug, position, color, title, summary, body, features, deliverables) values
  (true, null, null, null, 'corporate-web-design', 0, 'orange', 'Corporate web design', 'Fast, beautiful company websites that explain what you do in five seconds and turn visitors into enquiries.', 'Your website is often the first meeting with a client. We design and build corporate sites that feel premium, load instantly and are easy for your team to update.

Every site comes with a content management system, SEO foundations and analytics, so it keeps working after launch.', '[{"title":"Custom design","text":"No templates. A look built around your brand and your buyers."},{"title":"Editable content","text":"Update every text, image and page yourself, no developer needed."},{"title":"Motion that guides","text":"Tasteful animation that draws the eye to what matters."},{"title":"SEO ready","text":"Clean markup, fast pages and structured data from day one."}]'::jsonb, '[{"text":"Brand-aligned UI design"},{"text":"Responsive website"},{"text":"CMS with page sections"},{"text":"Analytics and SEO setup"},{"text":"Training session"}]'::jsonb),
  (true, null, null, null, 'web-software-apps', 1, 'blue', 'Web software & apps', 'Dashboards, portals, SaaS products and internal tools, engineered to scale and pleasant to use.', 'When a spreadsheet or an off-the-shelf tool stops being enough, we build the software your business actually needs.

We plan the data model with you, design the flows, and ship in short sprints with a live staging link.', '[{"title":"Product thinking","text":"We challenge scope so you launch sooner with what matters."},{"title":"Solid architecture","text":"Typed code, tests and a database designed for growth."},{"title":"Roles and security","text":"Sign-in, permissions and audit trails done properly."},{"title":"Integrations","text":"Payments, email, CRMs, ERPs and any API you use."}]'::jsonb, '[{"text":"Product scope and roadmap"},{"text":"UX flows and UI design"},{"text":"Web application"},{"text":"Admin panel"},{"text":"Documentation and handover"}]'::jsonb),
  (true, null, null, null, 'e-commerce', 2, 'lime', 'E-commerce', 'Online stores on Shopify, WooCommerce or custom stacks, with payments, shipping and marketing wired in.', 'We build stores that sell: quick product pages, a checkout without friction, and the back-office tools you need to run it.

Payments with Razorpay or Stripe, shipping with Shiprocket, and marketing pixels are set up and tested before launch.', '[{"title":"Conversion-first UX","text":"Product pages and checkout designed around buying."},{"title":"Payments and shipping","text":"Razorpay, Stripe, PayPal, Shiprocket and more."},{"title":"Catalogue tools","text":"Bulk import, variants, stock and discounts."},{"title":"Growth ready","text":"Pixels, feeds and email flows from day one."}]'::jsonb, '[{"text":"Store design"},{"text":"Shopify, WooCommerce or custom build"},{"text":"Payment and shipping setup"},{"text":"Product import"},{"text":"Launch checklist"}]'::jsonb),
  (true, null, null, null, 'seo-performance', 3, 'sky', 'SEO & performance', 'Technical SEO, content structure and Core Web Vitals work that moves you up the results page.', 'Rankings follow speed, structure and useful content. We audit your site, fix what slows it down, and build a plan for the searches your buyers make.

You get a clear report every month, in plain language.', '[{"title":"Technical audit","text":"Crawl, indexation, schema and site speed checked in depth."},{"title":"Core Web Vitals","text":"We make pages load and respond instantly."},{"title":"Content plan","text":"Topics and pages mapped to real search demand."},{"title":"Local SEO","text":"Google Business Profile and local listings tuned."}]'::jsonb, '[{"text":"Free audit report"},{"text":"Speed optimisation"},{"text":"Keyword and content map"},{"text":"Schema markup"},{"text":"Monthly reporting"}]'::jsonb),
  (true, null, null, null, 'management-maintenance', 4, 'violet', 'Management & maintenance', 'Updates, backups, monitoring and small improvements every month, so your site never falls behind.', 'Websites and apps need care. We keep yours secure, fast and up to date, and handle the small changes your team needs.

Every plan includes uptime monitoring and a 24-hour response time.', '[{"title":"Security updates","text":"Frameworks, plugins and servers kept patched."},{"title":"Backups","text":"Daily backups with tested restores."},{"title":"Monitoring","text":"Uptime and error alerts go straight to us."},{"title":"Change hours","text":"Monthly hours for content and feature tweaks."}]'::jsonb, '[{"text":"Monthly maintenance plan"},{"text":"Uptime monitoring"},{"text":"Backups"},{"text":"Priority support"},{"text":"Monthly health report"}]'::jsonb),
  (true, null, null, null, 'business-automation', 5, 'yellow', 'Business automation', 'Connect your tools and remove repetitive work: leads, invoices, reports and approvals that run themselves.', 'Most teams lose hours a week copying data between apps. We map your processes and automate them with n8n, Zapier or custom code.

The result: fewer mistakes, faster responses and a team focused on real work.', '[{"title":"Process mapping","text":"We find the tasks worth automating first."},{"title":"Tool integrations","text":"CRMs, sheets, accounting, WhatsApp and email."},{"title":"Custom workflows","text":"n8n, Zapier or code, whatever fits best."},{"title":"Dashboards","text":"Live numbers instead of weekly spreadsheets."}]'::jsonb, '[{"text":"Automation audit"},{"text":"Workflow build"},{"text":"Integrations"},{"text":"Reporting dashboard"},{"text":"Team training"}]'::jsonb),
  (true, null, null, null, 'digital-marketing', 6, 'pink', 'Digital marketing', 'Performance ads, social media and email campaigns measured against one thing: revenue.', 'We plan, launch and optimise campaigns on Google, Meta and email, with tracking you can trust.

Creative, landing pages and analytics come from the same team, so nothing gets lost between agencies.', '[{"title":"Paid ads","text":"Google and Meta campaigns tuned every week."},{"title":"Social media","text":"Content calendars and creatives that fit your brand."},{"title":"Email and WhatsApp","text":"Automated flows that bring customers back."},{"title":"Tracking","text":"Pixels, conversions and dashboards set up correctly."}]'::jsonb, '[{"text":"Marketing plan"},{"text":"Ad campaigns"},{"text":"Landing pages"},{"text":"Creative assets"},{"text":"Monthly performance report"}]'::jsonb),
  (true, null, null, null, 'mobile-apps', 7, 'red', 'Mobile apps', 'iOS and Android apps with React Native or Flutter, from prototype to the App Store and Play Store.', 'We design and build mobile apps that feel native, work offline and are a joy to use.

One codebase for both platforms keeps costs down, and we handle store submission and updates.', '[{"title":"Cross-platform","text":"React Native or Flutter for iOS and Android."},{"title":"Native feel","text":"Smooth gestures, notifications and offline mode."},{"title":"Backend included","text":"APIs, auth and an admin panel to run the app."},{"title":"Store launch","text":"Listings, screenshots and review handled for you."}]'::jsonb, '[{"text":"App design"},{"text":"iOS and Android app"},{"text":"Backend and admin"},{"text":"Store submission"},{"text":"Analytics and crash reporting"}]'::jsonb),
  (true, null, null, null, 'ai-agents-automation', 8, 'ink', 'AI agents & automation', 'AI assistants, chatbots and agents built on Claude and other models, connected to your data and tools.', 'AI is useful when it is connected to your real work. We build assistants that answer customers, agents that handle back-office tasks, and search over your own documents.

We start with one measurable use case, prove it, then expand.', '[{"title":"Support assistants","text":"Answer customers on your site and WhatsApp, around the clock."},{"title":"Internal agents","text":"Draft, summarise, classify and update records for your team."},{"title":"Knowledge search","text":"Ask questions over your documents and data."},{"title":"Safe by design","text":"Guardrails, human review and clear logs."}]'::jsonb, '[{"text":"Use-case workshop"},{"text":"AI agent or assistant"},{"text":"Tool and data integrations"},{"text":"Evaluation and guardrails"},{"text":"Usage dashboard"}]'::jsonb)
on conflict (slug) do nothing;

